def encode(message):
    vowels = 'aeiouAEIOU'
    result = ''
    for char in message:
        if char in vowels:
            # Find the next vowel in the alphabet
            next_vowel = chr((ord(char) - ord('a') + 2) % 26 + ord('a'))
            result += next_vowel
        else:
            # Swap case
            result += char.swapcase()
    return result

